#!/usr/bin/env python3
"""Render final artifacts only after all measurement processes have terminal success."""
from pathlib import Path
import json,statistics,shlex,re
R=Path(__file__).resolve().parent

def load(path):return json.loads((R/path).read_text())
def fmt(x,n=1):return 'n/d' if x is None else f'{float(x):.{n}f}'
def med(rows,key):
 v=[x[key] for x in rows if x.get(key) is not None];return statistics.median(v) if v else None
def table(columns,rows):return '| '+' | '.join(columns)+' |\n| '+' | '.join(['---']*len(columns))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)+'\n'
def code(x):return '```json\n'+json.dumps(x,indent=2,ensure_ascii=False)+'\n```'
def cfgvalue(c,k,default=None):return c['args'][c['args'].index(k)+1] if k in c['args'] else default

def ready(source,model,port):
 c=load('configs/'+source+'.json');c['port']=port;c['log']=str(R/'logs'/f'{model}-ready-engine.log')
 path=R/'configs'/f'{model}-best-runtime.json';path.write_text(json.dumps(c,indent=2)+'\n')
 gpu='0,1' if c.get('gpu')==[0,1] or '--expert-cache-device1' in c['args'] else '0'
 command=['/srv/ai/strata/.venv/bin/python','-m','serve.server','--engine','strata','--config',str(path),'--host','127.0.0.1','--port',str(port)]
 script=R/'configs'/f'run-{model}-best.sh';script.write_text('#!/usr/bin/env bash\nset -euo pipefail\ncd /srv/ai/strata\nexport CUDA_VISIBLE_DEVICES='+gpu+'\nexec '+shlex.join(command)+'\n');script.chmod(0o755)
 return c

